import { useEffect, useId, useRef } from 'react';
import './command-palette.css';

export type Command = { id: string; label: string; group: string; hint?: string };
type Props = { open: boolean; query: string; groups: readonly { name: string; commands: readonly Command[] }[]; recent: readonly Command[]; activeId?: string; onQueryChange: (query: string) => void; onActiveChange: (id: string) => void; onChoose: (command: Command) => void; onClose: () => void };

export function CommandPalette({ open, query, groups, recent, activeId, onQueryChange, onActiveChange, onChoose, onClose }: Props) {
  const uid = useId(), input = useRef<HTMLInputElement>(null);
  const shown = query ? groups : recent.length ? [{ name: 'Recent', commands: recent }] : groups;
  const commands = shown.flatMap(group => group.commands);
  useEffect(() => { if (open) requestAnimationFrame(() => input.current?.focus()); }, [open]);
  if (!open) return null;
  function move(delta: number) { if (!commands.length) return; const index = Math.max(0, commands.findIndex(command => command.id === activeId)); onActiveChange(commands[(index + delta + commands.length) % commands.length].id); }
  return <div className="paletteBackdrop" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}>
    <section className="commandPalette" role="dialog" aria-modal="true" aria-labelledby={`${uid}-title`} onKeyDown={event => { if (event.key === 'Escape') onClose(); if (event.key === 'ArrowDown') { event.preventDefault(); move(1); } if (event.key === 'ArrowUp') { event.preventDefault(); move(-1); } if (event.key === 'Enter') { const command = commands.find(item => item.id === activeId); if (command) { event.preventDefault(); onChoose(command); } } }}>
      <h1 id={`${uid}-title`} className="visuallyHidden">Command palette</h1><div className="paletteSearch"><span aria-hidden="true">⌕</span><input ref={input} value={query} onChange={event => onQueryChange(event.target.value)} role="combobox" aria-label="Search commands" aria-expanded="true" aria-controls={`${uid}-results`} aria-activedescendant={activeId ? `${uid}-${activeId}` : undefined} autoComplete="off" /></div>
      <div className="paletteResults" id={`${uid}-results`} role="listbox">{commands.length === 0 ? <div className="paletteEmpty"><span aria-hidden="true">◇</span><strong>No commands found</strong><span>Try a different search.</span></div> : shown.map(group => <section key={group.name} role="group" aria-labelledby={`${uid}-group-${group.name}`}><h2 id={`${uid}-group-${group.name}`}>{group.name}</h2>{group.commands.map(command => <button id={`${uid}-${command.id}`} role="option" aria-selected={command.id === activeId} type="button" key={command.id} onPointerMove={() => onActiveChange(command.id)} onClick={() => onChoose(command)}><span>{command.label}</span>{command.hint && <kbd>{command.hint}</kbd>}</button>)}</section>)}</div>
    </section>
  </div>;
}

