.paletteBackdrop { position: fixed; inset: 0; z-index: 100; display: grid; place-items: start center; padding: min(16dvh, 8rem) 1rem 1rem; background: rgb(15 15 20 / .5); }
.commandPalette { inline-size: min(38rem, 100%); overflow: hidden; border: 1px solid #d2d2da; border-radius: .75rem; background: #fff; color: #202026; box-shadow: 0 1.5rem 4rem rgb(0 0 0 / .25); }
.paletteSearch { display: flex; align-items: center; gap: .65rem; padding: .75rem 1rem; border-block-end: 1px solid #dfdfe5; } .paletteSearch > span { color: #696974; font-size: 1.25rem; } .paletteSearch input { min-inline-size: 0; flex: 1; border: 0; outline: 0; background: transparent; color: inherit; font: inherit; font-size: 1rem; }
.paletteResults { max-block-size: min(24rem, 55dvh); overflow-y: auto; padding: .5rem; } .paletteResults section + section { margin-block-start: .5rem; } .paletteResults h2 { margin: .25rem .5rem; color: #74747e; font-size: .6875rem; letter-spacing: .06em; text-transform: uppercase; }
.paletteResults button { inline-size: 100%; min-block-size: 2.5rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: .55rem .65rem; border: 0; border-radius: .4rem; background: transparent; color: inherit; font: inherit; text-align: start; cursor: pointer; } .paletteResults button[aria-selected='true'] { background: #e7e6ff; color: #2e287c; } .paletteResults kbd { color: #666670; font: inherit; font-size: .75rem; }
.paletteEmpty { display: grid; justify-items: center; gap: .35rem; padding: 3rem 1rem; color: #6b6b75; text-align: center; } .paletteEmpty > span:first-child { font-size: 2rem; } .paletteEmpty strong { color: #29292f; }
.visuallyHidden { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
@media (max-width: 540px) { .paletteBackdrop { align-items: end; padding: 0; } .commandPalette { border-radius: .75rem .75rem 0 0; } .paletteResults { max-block-size: 60dvh; } }
